INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published, seo_description) VALUES ('ai-video', 'AI Video Production', 'Professional videos for your business — no camera, no studio, no actors.', 'Reels, ads and explainer videos made with AI — script, voiceover, captions and music included. Starting at ₹2,499.', '🎬 New', '/assets/icons/ai-video.svg', 'butter', '["Reels & ads", "Explainers", "AI voiceover", "Captions", "Bengali · Hindi · English"]', 'See video prices', 'We turn your offer, product or idea into a ready-to-post video using AI — scripted, voiced, captioned and edited for Instagram, Facebook, YouTube and WhatsApp. You get professional-looking videos in days, for a fraction of what a film shoot costs.', 'video', '', 'No camera needed', '["Script written for your business", "AI voiceover in Bengali, Hindi or English", "AI visuals, avatars or stock footage", "Captions / subtitles on every video", "Background music and sound effects", "Vertical (9:16) for Reels or horizontal (16:9) for YouTube", "2 rounds of changes included"]', '["Shops and restaurants announcing an offer", "Coaching centres and clinics explaining their services", "Businesses that want regular Reels without filming"]', '## Pricing

- **Under 1 minute** (15–45 sec Reel, ad or offer video) — **₹2,499** · ready in 2–3 days
- **1 minute** (promo or product video) — **₹3,999** · ready in 3–4 days
- **Up to 5 minutes** (explainer, product demo or course intro) — **₹11,999** · ready in 5–7 days
- **Up to 10 minutes** (detailed explainer, training or YouTube video) — **₹19,999** · ready in 7–10 days

Every price includes the script, AI voiceover, visuals, captions, background music and 2 rounds of changes. One-time payment: 50% to start, and the remaining 50% after you approve the final video.

## Add-ons

- **Extra language version** (Bengali, Hindi or English) — ₹999 per video
- **Urgent delivery** in 24–48 hours (videos up to 1 minute) — +₹1,000
- **Monthly Reel pack** — 8 short videos (under 1 minute) every month for ₹14,999

## How it works

1. **Tell us what you need** — share your business, offer or idea on WhatsApp, with any photos or logo.
2. **Approve the script** — we write it first, so nothing is made until you''re happy with the words.
3. **We create the video** — AI voiceover, visuals, captions and music, edited to your length and format.
4. **Review and refine** — you watch a preview and ask for changes (2 rounds included).
5. **Post it everywhere** — you get the final file, ready for Instagram, Facebook, YouTube and WhatsApp status.

## Why AI video?

Video gets far more attention than a photo post, but filming takes time, equipment and money. With AI we can make clean, professional videos without a camera, studio or actors — so you can post regularly without the cost of a shoot.', 'Get my AI video', 0, 6, 1, 'AI video production for local businesses in Purulia and West Bengal: Reels, ads and explainer videos with script, AI voiceover, captions and music. Videos under 1 minute from ₹2,499.');
